 * Install: npx shadcn@latest add https://axiestudio.github.io/UI_Engine/registry/r/radial-gauge.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
// Vendored from Bklit UI (MIT) — https://github.com/bklit/bklit-ui · packages/ui/src/charts/chart-center-typography.ts — fetched 2026-09-01
// Adapted: none (verbatim copy, imports unchanged)
/**
 * Fluid typography for pie / ring / gauge center labels.
 *
 * Uses CSS container query units (`cqw`) so values scale with the center
 * hole — not the viewport — which keeps stat text readable on small charts.
 */
export const chartCenterContainerClassName =
  "@container/chart-center size-full min-w-0";

/** Primary stat — ~22% of center width, clamped between text-sm and text-3xl. */
export const chartCenterValueClassName =
  "font-bold tabular-nums leading-none text-[clamp(0.75rem,22cqw,1.875rem)]";

/** Supporting label — ~9% of center width, clamped between 10px and text-xs. */
export const chartCenterLabelClassName =
  "max-w-full truncate leading-tight text-[clamp(0.625rem,9cqw,0.75rem)]";

/**
 * radial-gauge — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://axiestudio.github.io/UI_Engine/registry/r/radial-gauge.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
// Vendored from Bklit UI (MIT) — https://github.com/bklit/bklit-ui · packages/ui/src/charts/chart-stat-flow.tsx — fetched 2026-09-01
// Adapted: NumberFlow → in-repo SlidingNumber primitive (motion-primitives); reduced-motion renders static text
"use client";

import { type ReactNode, useMemo } from "react";
import { useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";
import { SlidingNumber } from "@/components/primitives/sliding-number";

/** Subset of `Intl.NumberFormatOptions` supported by the stat display */
export interface ChartStatFlowFormat {
  notation?: "standard" | "compact";
  compactDisplay?: "short" | "long";
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  minimumIntegerDigits?: number;
  minimumSignificantDigits?: number;
  maximumSignificantDigits?: number;
  style?: "decimal" | "percent" | "currency";
  currency?: string;
  currencyDisplay?: "symbol" | "narrowSymbol" | "code" | "name";
  unit?: string;
  unitDisplay?: "short" | "long" | "narrow";
}

export const defaultChartStatFlowFormat: ChartStatFlowFormat = {
  notation: "standard",
  maximumFractionDigits: 0,
};

function formatStatValue(
  value: number,
  formatOptions: ChartStatFlowFormat,
  prefix?: string,
  suffix?: string
): string {
  const formatted = new Intl.NumberFormat(undefined, formatOptions).format(
    value
  );
  return `${prefix ?? ""}${formatted}${suffix ?? ""}`;
}

export interface ChartStatFlowProps {
  value: number;
  /** Center label — omit or pass "" to render the value only */
  label?: string;
  formatOptions?: ChartStatFlowFormat;
  prefix?: string;
  suffix?: string;
  valueClassName?: string;
  labelClassName?: string;
  icon?: ReactNode;
}

/**
 * Shared value + label stack using SlidingNumber (same layout as pie / ring centers).
 * Parent should provide flex alignment and sizing when needed.
 */
export function ChartStatFlow({
  value,
  label,
  formatOptions = defaultChartStatFlowFormat,
  prefix,
  suffix,
  valueClassName = "text-2xl font-bold",
  labelClassName = "text-xs",
  icon,
}: ChartStatFlowProps) {
  const reduce = useReducedMotion();
  const staticValue = useMemo(
    () => formatStatValue(value, formatOptions, prefix, suffix),
    [value, formatOptions, prefix, suffix]
  );

  // SlidingNumber animates raw digits; feed it the plain number and keep
  // prefix/suffix as sibling spans so digits slide without re-parsing.
  const slidingValue = useMemo(() => {
    const opts: Intl.NumberFormatOptions = { ...formatOptions };
    // strip style/unit concerns — SlidingNumber handles plain decimals only
    void opts;
    const rounded = Number(
      new Intl.NumberFormat("en-US", {
        minimumFractionDigits: formatOptions?.minimumFractionDigits,
        maximumFractionDigits: formatOptions?.maximumFractionDigits ?? 2,
      }).format(value)
    );
    return rounded;
  }, [value, formatOptions]);

  return (
    <>
      {icon ? (
        <div className="mb-2 flex h-12 w-12 items-center justify-center rounded-full bg-muted/50">
          {icon}
        </div>
      ) : null}
      <span className={cn("text-foreground tabular-nums", valueClassName)}>
        {prefix ? <span>{prefix}</span> : null}
        {reduce ? (
          <span>{staticValue.slice(prefix?.length ?? 0, staticValue.length - (suffix?.length ?? 0))}</span>
        ) : (
          <SlidingNumber value={slidingValue} />
        )}
        {suffix ? <span>{suffix}</span> : null}
      </span>
      {label ? (
        <span className={cn("mt-0.5 text-chart-label", labelClassName)}>
          {label}
        </span>
      ) : null}
    </>
  );
}

ChartStatFlow.displayName = "ChartStatFlow";

/**
 * radial-gauge — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://axiestudio.github.io/UI_Engine/registry/r/radial-gauge.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
// Vendored from Bklit UI (MIT) — https://github.com/bklit/bklit-ui · packages/ui/src/charts/gauge-label-layout.tsx — fetched 2026-09-01
// Adapted: none (verbatim copy, imports unchanged)
"use client";

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import {
  chartCenterContainerClassName,
  chartCenterLabelClassName,
  chartCenterValueClassName,
} from "./chart-center-typography";
import {
  ChartStatFlow,
  type ChartStatFlowFormat,
  defaultChartStatFlowFormat,
} from "./chart-stat-flow";

export type GaugeLabelPlacement = "top" | "bottom" | "left" | "right";
export type GaugeLabelAlign = "start" | "center" | "end";

export interface GaugeLabelShellProps {
  centerValue: number;
  defaultLabel?: string;
  prefix?: string;
  suffix?: string;
  formatOptions?: ChartStatFlowFormat;
  align?: GaugeLabelAlign;
  className?: string;
}

const labelAlignClass: Record<GaugeLabelAlign, string> = {
  start: "items-start text-left",
  center: "items-center text-center",
  end: "items-end text-right",
};

export function GaugeLabelShell({
  centerValue,
  defaultLabel = "Total",
  prefix,
  suffix,
  formatOptions = defaultChartStatFlowFormat,
  align = "center",
  className,
}: GaugeLabelShellProps) {
  return (
    <div
      className={cn(
        chartCenterContainerClassName,
        "flex min-w-0 flex-col",
        labelAlignClass[align],
        className
      )}
    >
      <ChartStatFlow
        formatOptions={formatOptions}
        label={defaultLabel}
        labelClassName={cn(
          chartCenterLabelClassName,
          "text-[length:var(--chart-foreground-muted)]"
        )}
        prefix={prefix}
        suffix={suffix}
        value={centerValue}
        valueClassName={cn(
          chartCenterValueClassName,
          "text-[length:var(--chart-foreground)]"
        )}
      />
    </div>
  );
}

const crossAxisSelf: Record<GaugeLabelAlign, string> = {
  start: "self-start",
  center: "self-center",
  end: "self-end",
};

const crossAxisAlign: Record<GaugeLabelAlign, string> = {
  start: "items-start",
  center: "items-center",
  end: "items-end",
};

const inlineAxisAlign: Record<GaugeLabelAlign, string> = {
  start: "justify-start",
  center: "justify-center",
  end: "justify-end",
};

export function GaugeLabelLayout({
  placement,
  align,
  label,
  children,
  className,
}: {
  placement: GaugeLabelPlacement;
  align: GaugeLabelAlign;
  label: ReactNode | null;
  children: ReactNode;
  className?: string;
}) {
  if (!label) {
    return <div className={cn("w-full min-w-0", className)}>{children}</div>;
  }

  if (placement === "top") {
    return (
      <div
        className={cn(
          "flex w-full min-w-0 flex-col gap-3",
          crossAxisAlign[align],
          className
        )}
      >
        <div className={crossAxisSelf[align]}>{label}</div>
        <div className="w-full min-w-0">{children}</div>
      </div>
    );
  }

  if (placement === "bottom") {
    return (
      <div
        className={cn(
          "flex w-full min-w-0 flex-col gap-3",
          crossAxisAlign[align],
          className
        )}
      >
        <div className="w-full min-w-0">{children}</div>
        <div className={crossAxisSelf[align]}>{label}</div>
      </div>
    );
  }

  if (placement === "left") {
    return (
      <div
        className={cn(
          "flex w-full min-w-0 items-center gap-4",
          inlineAxisAlign[align],
          className
        )}
      >
        <div className="shrink-0">{label}</div>
        <div className="min-w-0 flex-1">{children}</div>
      </div>
    );
  }

  return (
    <div
      className={cn(
        "flex w-full min-w-0 items-center gap-4",
        inlineAxisAlign[align],
        className
      )}
    >
      <div className="min-w-0 flex-1">{children}</div>
      <div className="shrink-0">{label}</div>
    </div>
  );
}

/**
 * radial-gauge — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://axiestudio.github.io/UI_Engine/registry/r/radial-gauge.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
// Vendored from Bklit UI (MIT) — https://github.com/bklit/bklit-ui · packages/ui/src/charts/gauge.tsx — fetched 2026-09-01
// Adapted: ParentSize/geometryScrubbing removed (fixed-size mode only); zoneFill callback shim for per-notch zone colors; PieCenterShell replaced with inline ChartStatFlow center (no pie-context dependency)
"use client";

import { motion, type Transition, useReducedMotion } from "motion/react";
import { type ReactNode, useId, useMemo } from "react";
import { cn } from "@/lib/utils";
import {
  type ChartStatFlowFormat,
  ChartStatFlow,
  defaultChartStatFlowFormat,
} from "./chart-stat-flow";
import {
  type GaugeLabelAlign,
  GaugeLabelLayout,
  type GaugeLabelPlacement,
  GaugeLabelShell,
} from "./gauge-label-layout";
import {
  type ComputedNotch,
  collectGaugeDefsElements,
  createNotchPath,
  DEFAULT_ACTIVE_FILL_OPACITY,
  DEFAULT_ACTIVE_GRADIENT,
  DEFAULT_INACTIVE_FILL_OPACITY,
  DEFAULT_LINEAR_GAUGE_HEIGHT,
  interpolateGaugeHex,
  resolveGaugeActiveFill,
  resolveGaugeBgFill,
} from "./notch-gauge-shared";

const DEFAULT_NOTCH_ENTER_TRANSITION: Transition = {
  type: "spring",
  stiffness: 300,
  damping: 20,
};

export type GaugeOrientation = "arc" | "linear";

export interface GaugeProps {
  /** Arc (default) or horizontal linear notch track */
  orientation?: GaugeOrientation;
  /** Fill level 0–100 */
  value: number;
  /** Number of notches */
  totalNotches?: number;
  /** Percentage of the track reserved for gaps between notches */
  spacing?: number;
  notchCornerRadius?: number;
  /** `true` = rectangular notches; `false` = tapered toward center / midline */
  uniformWidth?: boolean;
  startAngle?: number;
  endAngle?: number;
  useGradient?: boolean;
  activeGradient?: readonly [string, string];
  inactiveGradient?: readonly [string, string];
  /** Center statistic — omit to hide the label block */
  centerValue?: number;
  defaultLabel?: string;
  prefix?: string;
  suffix?: string;
  formatOptions?: ChartStatFlowFormat;
  /** Label position for `orientation="linear"`. Arc gauges always overlay center. */
  labelPlacement?: GaugeLabelPlacement;
  /** Cross-axis alignment (start / center / end), same model as chart legend */
  labelAlign?: GaugeLabelAlign;
  inactiveFill?: string;
  /** Adapted shim: notch → fill color (zone mapping). Overrides activeFill. */
  zoneFill?: (notchFraction: number) => string;
  activeFill?: string;
  inactiveFillOpacity?: number;
  activeFillOpacity?: number;
  children?: ReactNode;
  className?: string;
  /** Adapted: fixed size mode (no ParentSize) — width required */
  width: number;
  height?: number;
  notchLengthPercent?: number;
  /** Linear only — notch width as % of each slot (default 80) */
  notchWidthPercent?: number;
  enterTransition?: Transition;
  enterStaggerScale?: number;
}

interface GaugeInnerProps extends Omit<GaugeProps, "className"> {
  width: number;
  height: number;
}

function GaugeNotchSvg({
  notches,
  width,
  height,
  notchCornerRadius,
  cornerDepth,
  notchTransition,
  stagger,
  defsChildren,
  useThemePaletteGradient,
  themeActiveGradientId,
  resolvedInactiveFillOpacity,
  resolvedActiveFillOpacity,
  resolveBgFill,
  resolveActiveFill,
}: {
  notches: ComputedNotch[];
  width: number;
  height: number;
  notchCornerRadius: number;
  cornerDepth: number;
  notchTransition: Transition;
  stagger: number;
  defsChildren: ReactNode[];
  useThemePaletteGradient: boolean;
  themeActiveGradientId: string;
  resolvedInactiveFillOpacity: number;
  resolvedActiveFillOpacity: number;
  resolveBgFill: (index: number) => string;
  resolveActiveFill: (notch: ComputedNotch) => string;
}) {
  return (
    <svg
      aria-hidden="true"
      className="block w-full overflow-visible"
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      width={width}
    >
      {defsChildren.length > 0 || useThemePaletteGradient ? (
        <defs>
          {useThemePaletteGradient ? (
            <linearGradient
              id={themeActiveGradientId}
              x1="0%"
              x2="100%"
              y1="0%"
              y2="0%"
            >
              <stop offset="0%" stopColor="var(--chart-1)" />
              <stop offset="100%" stopColor="var(--chart-5)" />
            </linearGradient>
          ) : null}
          {defsChildren}
        </defs>
      ) : null}
      {notches.map((notch) => {
        const pathD = createNotchPath(
          notch.points,
          notchCornerRadius,
          cornerDepth
        );
        return (
          <motion.path
            animate={{ opacity: 1, scale: 1 }}
            d={pathD}
            fill={resolveBgFill(notch.index)}
            fillOpacity={resolvedInactiveFillOpacity}
            initial={{ opacity: 0, scale: 0 }}
            key={`bg-${notch.index}`}
            style={{
              transformOrigin: `${notch.xCenter}px ${notch.yCenter}px`,
            }}
            transition={{
              ...notchTransition,
              delay: notch.index * 0.015 * stagger,
            }}
          />
        );
      })}
      {notches
        .filter((n) => n.isActive)
        .map((notch) => {
          const pathD = createNotchPath(
            notch.points,
            notchCornerRadius,
            cornerDepth
          );
          return (
            <motion.path
              animate={{ opacity: 1, scale: 1 }}
              d={pathD}
              fill={resolveActiveFill(notch)}
              fillOpacity={resolvedActiveFillOpacity}
              initial={{ opacity: 0, scale: 0 }}
              key={`active-${notch.index}`}
              style={{
                transformOrigin: `${notch.xCenter}px ${notch.yCenter}px`,
              }}
              transition={{
                ...notchTransition,
                delay: (0.3 + notch.index * 0.02) * stagger,
              }}
            />
          );
        })}
    </svg>
  );
}

function useGaugeFillState(props: GaugeInnerProps) {
  const {
    useGradient = false,
    activeGradient,
    inactiveGradient,
    inactiveFill,
    activeFill,
    inactiveFillOpacity,
    activeFillOpacity,
    children,
    totalNotches = 40,
  } = props;

  const themeActiveGradientId = `gauge-theme-active-${useId().replace(/:/g, "")}`;
  const defsChildren = useMemo(
    () => collectGaugeDefsElements(children),
    [children]
  );

  const hasCustomInactive =
    inactiveFill !== undefined && inactiveFill.length > 0;
  const hasCustomActive = activeFill !== undefined && activeFill.length > 0;

  const activeGrad0 = activeGradient?.[0] ?? DEFAULT_ACTIVE_GRADIENT[0];
  const activeGrad1 = activeGradient?.[1] ?? DEFAULT_ACTIVE_GRADIENT[1];
  const inactiveGrad0 = inactiveGradient?.[0] ?? activeGrad0;
  const inactiveGrad1 = inactiveGradient?.[1] ?? activeGrad1;
  const useThemePaletteGradient = useGradient && activeGradient === undefined;

  return {
    themeActiveGradientId,
    defsChildren,
    hasCustomInactive,
    hasCustomActive,
    activeGrad0,
    activeGrad1,
    inactiveGrad0,
    inactiveGrad1,
    useThemePaletteGradient,
    resolvedActiveFillOpacity: activeFillOpacity ?? DEFAULT_ACTIVE_FILL_OPACITY,
    resolvedInactiveFillOpacity:
      inactiveFillOpacity ?? DEFAULT_INACTIVE_FILL_OPACITY,
    totalNotches,
  };
}

function GaugeArcInner(props: GaugeInnerProps) {
  const {
    value,
    totalNotches = 40,
    spacing = 25,
    notchCornerRadius = 0,
    uniformWidth = false,
    width,
    height,
    startAngle = 135,
    endAngle = 405,
    useGradient = false,
    centerValue,
    defaultLabel = "Total",
    prefix,
    suffix,
    formatOptions = defaultChartStatFlowFormat,
    zoneFill,
    inactiveFill,
    activeFill,
    notchLengthPercent = 100,
    enterTransition,
    enterStaggerScale = 1,
  } = props;

  const prefersReducedMotion = useReducedMotion();
  const fillState = useGaugeFillState(props);

  const notchTransition: Transition = prefersReducedMotion
    ? { duration: 0 }
    : (enterTransition ?? DEFAULT_NOTCH_ENTER_TRANSITION);
  const stagger = Math.max(0.25, Math.min(2.5, enterStaggerScale));

  const size = Math.min(width, height);
  const centerX = width / 2;
  const centerY = height / 2;
  const outerRadius = size * 0.42;
  const innerRadiusBase = size * 0.28;
  const defaultRadialDepth = outerRadius - innerRadiusBase;
  const depthFactor = Math.min(100, Math.max(5, notchLengthPercent)) / 100;
  const notchLength = defaultRadialDepth * depthFactor;
  const innerRadius = outerRadius - notchLength;

  const activeNotches = Math.round((value / 100) * totalNotches);
  const totalAngle = endAngle - startAngle;
  const availableAngle = totalAngle * (1 - spacing / 100);
  const notchAngle = totalNotches > 0 ? availableAngle / totalNotches : 0;
  const gapDen = totalNotches - 1 > 0 ? totalNotches - 1 : 1;
  const gapAngle = (totalAngle * (spacing / 100)) / gapDen;

  const notches = useMemo(() => {
    return Array.from({ length: totalNotches }, (_, i) => {
      const angle = startAngle + i * (notchAngle + gapAngle) + notchAngle / 2;
      const radians = (angle * Math.PI) / 180;
      const arcNotchWidth = notchAngle * 0.8;
      const halfWidth = (arcNotchWidth * Math.PI) / 180 / 2;

      const x1 = centerX + Math.cos(radians - halfWidth) * outerRadius;
      const y1 = centerY + Math.sin(radians - halfWidth) * outerRadius;
      const x2 = centerX + Math.cos(radians + halfWidth) * outerRadius;
      const y2 = centerY + Math.sin(radians + halfWidth) * outerRadius;

      let x3: number;
      let y3: number;
      let x4: number;
      let y4: number;

      if (uniformWidth) {
        const perpX = Math.cos(radians);
        const perpY = Math.sin(radians);
        x3 = x2 - perpX * notchLength;
        y3 = y2 - perpY * notchLength;
        x4 = x1 - perpX * notchLength;
        y4 = y1 - perpY * notchLength;
      } else {
        x3 = centerX + Math.cos(radians + halfWidth) * innerRadius;
        y3 = centerY + Math.sin(radians + halfWidth) * innerRadius;
        x4 = centerX + Math.cos(radians - halfWidth) * innerRadius;
        y4 = centerY + Math.sin(radians - halfWidth) * innerRadius;
      }

      const denom = totalNotches > 1 ? totalNotches - 1 : 1;
      const gradientColor =
        useGradient && !fillState.useThemePaletteGradient
          ? interpolateGaugeHex(
              fillState.activeGrad0,
              fillState.activeGrad1,
              i / denom
            )
          : "var(--chart-1)";

      return {
        index: i,
        points: { x1, y1, x2, y2, x3, y3, x4, y4 },
        isActive: i < activeNotches,
        gradientColor,
        xCenter: centerX,
        yCenter: centerY,
      };
    });
  }, [
    totalNotches,
    notchAngle,
    gapAngle,
    centerX,
    centerY,
    outerRadius,
    innerRadius,
    activeNotches,
    startAngle,
    uniformWidth,
    notchLength,
    useGradient,
    fillState.useThemePaletteGradient,
    fillState.activeGrad0,
    fillState.activeGrad1,
  ]);

  const resolveBgFill = (notchIndex: number) =>
    resolveGaugeBgFill({
      notchIndex,
      totalNotches,
      hasCustomInactive: fillState.hasCustomInactive,
      inactiveFill,
      useThemePaletteGradient: fillState.useThemePaletteGradient,
      useGradient,
      inactiveGrad0: fillState.inactiveGrad0,
      inactiveGrad1: fillState.inactiveGrad1,
      arcTrackFill: "var(--border)",
      linearTrackFill: "var(--chart-scale-01)",
      linearMode: false,
    });

  const resolveActiveFill = (notch: ComputedNotch) => {
    if (zoneFill) {
      return zoneFill((notch.index + 1) / totalNotches);
    }
    return resolveGaugeActiveFill({
      notch,
      hasCustomActive: fillState.hasCustomActive,
      activeFill,
      useThemePaletteGradient: fillState.useThemePaletteGradient,
      themeActiveGradientId: fillState.themeActiveGradientId,
      useGradient,
      activeFillSolid: "var(--chart-1)",
    });
  };

  const showCenter = centerValue != null;

  return (
    <div className="relative w-full" style={{ height, width }}>
      <GaugeNotchSvg
        cornerDepth={notchLength}
        defsChildren={fillState.defsChildren}
        height={height}
        notchCornerRadius={notchCornerRadius}
        notches={notches}
        notchTransition={notchTransition}
        resolveActiveFill={resolveActiveFill}
        resolveBgFill={resolveBgFill}
        resolvedActiveFillOpacity={fillState.resolvedActiveFillOpacity}
        resolvedInactiveFillOpacity={fillState.resolvedInactiveFillOpacity}
        stagger={stagger}
        themeActiveGradientId={fillState.themeActiveGradientId}
        useThemePaletteGradient={fillState.useThemePaletteGradient}
        width={width}
      />
      {showCenter ? (
        <div
          className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center"
          style={{ paddingTop: size * 0.08 }}
        >
          {/* container = the donut hole (innerRadius ≈ 0.28 × size), matching
              RingCenter's model: the cqw type below scales to the hole, not the
              full box — otherwise the value paints over the notch band.
              container-type is set inline: Tailwind 3 core has no @container
              utility, and without a context cqw resolves to the viewport. */}
          <div
            className="@container/chart-center flex flex-col items-center overflow-hidden text-center"
            style={{ width: size * 0.56, containerType: "inline-size" }}
          >
            <ChartStatFlow
              formatOptions={formatOptions}
              label={defaultLabel}
              labelClassName="max-w-full truncate leading-tight text-[clamp(0.625rem,9cqw,0.75rem)] text-chart-label"
              prefix={prefix}
              suffix={suffix}
              value={centerValue}
              valueClassName="font-bold tabular-nums leading-none text-[clamp(0.75rem,22cqw,1.875rem)] whitespace-nowrap"
            />
          </div>
        </div>
      ) : null}
    </div>
  );
}

function GaugeLinearInner(props: GaugeInnerProps) {
  const {
    value,
    totalNotches = 40,
    spacing = 25,
    notchCornerRadius = 0,
    uniformWidth = true,
    width,
    height,
    useGradient = false,
    centerValue,
    defaultLabel = "Total",
    prefix,
    suffix,
    formatOptions = defaultChartStatFlowFormat,
    labelPlacement = "top",
    labelAlign = "start",
    zoneFill,
    inactiveFill,
    activeFill,
    notchLengthPercent = 100,
    notchWidthPercent = 80,
    enterTransition,
    enterStaggerScale = 1,
  } = props;

  const prefersReducedMotion = useReducedMotion();
  const fillState = useGaugeFillState(props);

  const notchTransition: Transition = prefersReducedMotion
    ? { duration: 0 }
    : (enterTransition ?? DEFAULT_NOTCH_ENTER_TRANSITION);
  const stagger = Math.max(0.25, Math.min(2.5, enterStaggerScale));

  const centerY = height / 2;
  const depthFactor = Math.min(100, Math.max(5, notchLengthPercent)) / 100;
  const outerOffset = (height / 2) * depthFactor;
  const taperRatio = 28 / 42;
