export function RadialGauge({
  value,
  min = 0,
  max = 100,
  zones = DEFAULT_ZONES,
  label,
  unit = "%",
  precision = 0,
  size = 220,
  orientation = "arc",
  notches = 40,
  showCenterValue = true,
  className,
